style.css:
@-moz-document domain("app.seesaw.me") {
/* ? Soft lavender Seesaw background */
    body {
        background-color: #f4eafa !important;
    }

    /* ? Shinobu */
    body::after {
        content: "";
        position: fixed;
        right: 20px;
        bottom: 0;

        width: 280px;
        height: 380px;

        background-image: url("https://static.wixstatic.com/media/396c43_15a81d230f8047719afaf27a7cea1105~mv2.jpg/v1/fill/w_480,h_480,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/396c43_15a81d230f8047719afaf27a7cea1105~mv2.jpg");

        background-size: contain;
        background-repeat: no-repeat;
        background-position: bottom right;

        mix-blend-mode: multiply;

        z-index: 999999;
        pointer-events: none;
    }
}
